#[cfg(test)]
mod extend_200402_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_extend_200402_codec() {
        let original = Extend200402 {
            stop_px: -123456789,
            min_qty: -123456789,
            max_price_levels: 1234,
            time_in_force: "a".to_string(),
            position_effect: "a".to_string(),
            covered_or_uncovered: 42,
            contract_account_code: "a".repeat(6),
            secondary_order_id: "a".repeat(16),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(Extend200402Ref::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        Extend200402::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = Extend200402::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

